const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'₹'+Number(n).toLocaleString('en-IN'),dateNow=()=>new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});
function save(){localStorage.setItem('classs-demo-v1',JSON.stringify(data));updateCount()}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}function updateCount(){$('#cart-count').textContent=data.cart.reduce((n,x)=>n+x.qty,0)}
function image(url,alt,cls='',eager=false){return `<img src="${esc(url)}" alt="${esc(alt)}" class="${cls}" loading="${eager?'eager':'lazy'}" decoding="async" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src='assets/image-unavailable.svg'">`}
function productCard(p){return `<article class="card product"><a class="card-media" href="#/product/${p.id}">${image(p.image,p.title)}${p.stock<10?'<span class="tag">Limited stock</span>':''}</a><div class="card-body"><div class="meta">${esc(p.category)}</div><h3><a href="#/product/${p.id}">${esc(p.title)}</a></h3><div class="stock">${p.stock>0?'In stock · '+p.stock+' available':'Out of stock'}</div><div class="card-bottom"><b>${money(p.price)}</b><button class="btn small outline" onclick="addCart('${p.id}')" ${p.stock<=0?'disabled':''}>Add to bag</button></div></div></article>`}
function projectCard(p){return `<article class="card"><a class="card-media" href="#/project/${p.id}">${image(p.image,p.title)}<span class="tag">${esc(p.difficulty)}</span></a><div class="card-body"><div class="meta">${esc(p.category)} / ${esc(p.technology)}</div><h3><a href="#/project/${p.id}">${esc(p.title)}</a></h3><p>${esc(p.description)}</p><div class="card-bottom"><span>Indicative ${money(p.budget)}</span><a class="text-link" href="#/project/${p.id}">View project</a></div></div></article>`}
function pageHead(k,title,desc){return `<div class="page-head"><div class="breadcrumb"><a href="#/">Home</a> / ${esc(k)}</div><span class="eyebrow">${esc(k)}</span><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>`}
function home(){return `<div class="container"><section class="hero"><div class="hero-copy"><span class="eyebrow hero-kicker">BUILD / BUY / PRINT / AUTOMATE</span><h1>Have an idea?<br><em>We build it.</em></h1><p>From your first circuit to your final-year breakthrough. Explore projects, find components, and make something that matters.</p><div class="button-row"><a class="btn blue" href="#/projects">${icon('project')}Explore projects</a><a class="btn outline" href="#/shop">${icon('bag')}Shop components</a></div><div class="proof"><span><b>${icon('check')}Custom builds</b>Made around your idea</span><span><b>${icon('check')}Technical support</b>From concept to completion</span></div></div><div class="hero-visual">${image(IMG.lab,'Robotics and engineering at work','',true)}<div class="hero-image-label"><span>ENGINEERING IN ACTION</span><b>Ideas become real here.</b></div><div class="floating-card"><span class="symbol">${icon('chip')}</span><span><strong>From idea to working build.</strong>Electronics · Software · Prototyping</span></div><a class="hero-component" href="#/product/esp32">${image(IMG.esp32,'ESP32 development board')}<span><small>YOUR NEXT BUILD STARTS HERE</small><b>ESP32 development board</b><span>Explore connected possibilities</span></span></a><div class="hero-caption"><small>ROBOTICS / AUTOMATION / INNOVATION</small><h3>Make your next idea move.</h3><a href="#/project/robotic-arm">Discover the project</a></div></div></section><div class="ways"><a class="way" href="#/projects"><span class="way-icon">${icon('project')}</span><div><b>Build a project</b><span>School, engineering & AI</span></div></a><a class="way" href="#/shop"><span class="way-icon">${icon('chip')}</span><div><b>Buy components</b><span>Electronics & robotics</span></div></a><a class="way" href="#/printing"><span class="way-icon">${icon('print')}</span><div><b>Print your design</b><span>Parts, models & prototypes</span></div></a><a class="way" href="#/services"><span class="way-icon">${icon('automate')}</span><div><b>Automate an idea</b><span>Industrial, digital & IoT</span></div></a></div><section class="section"><div class="section-header"><div><span class="eyebrow">Start with a possibility</span><h2>Projects worth building.</h2><p>Find an idea that fits your interests, skills and budget.</p></div><a class="text-link" href="#/projects">All projects</a></div><div class="grid">${data.projects.filter(p=>p.featured).slice(0,3).map(projectCard).join('')}</div></section></div><section class="shop-band section"><div class="container"><div class="section-header"><div><span class="eyebrow">Your workbench essentials</span><h2>Small parts. Big possibilities.</h2><p>Boards, sensors and kits for your next build.</p></div><a class="text-link" href="#/shop">Visit the shop</a></div><div class="grid four">${data.products.filter(p=>p.featured).slice(0,4).map(productCard).join('')}</div></div></section><div class="container"><section class="section" style="padding-top:55px"><div class="section-header"><div><span class="eyebrow">What comes next</span><h2>Explore the edge of technology.</h2></div><a class="text-link" href="#/future">Future Tech</a></div><div class="grid"><a class="card" href="#/future"><div class="card-media">${image(IMG.drone,'Drone technology')}</div><div class="card-body"><div class="meta">Drones & smart systems</div><h3>Take your ideas further.</h3></div></a><a class="card" href="#/printing"><div class="card-media">${image(IMG.printer,'Educational 3D printer')}</div><div class="card-body"><div class="meta">3D printing</div><h3>From CAD to something you can hold.</h3></div></a><a class="card" href="#/services"><div class="card-media">${image(IMG.esp32,'Connected electronics development board')}</div><div class="card-body"><div class="meta">Digital & IoT solutions</div><h3>Connect the physical and digital.</h3></div></a></div></section><section class="institution"><div class="institution-copy"><span class="eyebrow">For schools, colleges & businesses</span><h2>Build a better learning lab.</h2><p>From a classroom kit to a complete engineering lab. Share your requirements and we’ll help plan the components, training and support.</p><a class="btn" href="#/bulk">Discuss an institutional requirement</a></div><div class="institution-photo">${image(IMG.lab,'Engineering lab and robotics')}</div><div class="institution-list"><span>STEM & robotics labs</span><span>College project kits</span><span>Bulk component sourcing</span><span>Industrial prototypes</span></div></section></div>`}
function options(arr,value){return [...new Set(arr)].map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}
function filtered(kind){const list=kind==='shop'?data.products:data.projects;return list.filter(p=>{const text=[p.title,p.description,p.category,p.technology,p.branch,...(p.components||[]).map(id=>data.products.find(x=>x.id===id)?.title||id)].join(' ').toLowerCase();return (!filter.q||text.includes(filter.q.toLowerCase()))&&(filter.category==='All'||p.category===filter.category)&&(kind==='shop'||((filter.branch==='All'||p.branch===filter.branch)&&(filter.tech==='All'||p.technology===filter.tech)&&(filter.difficulty==='All'||p.difficulty===filter.difficulty)&&(filter.budget==='All'||p.budget<=Number(filter.budget))))})}
function catalogue(kind){const shop=kind==='shop',list=shop?data.products:data.projects;return `<div class="container catalogue-layout">${pageHead(shop?'Shop':'Project catalogue',shop?'Your next build starts here.':'Find your next great project.',shop?'Practical electronics, development boards and robotics essentials. Demo prices and availability.':'Explore ideas for school, engineering and industry. Search by project, technology or component.')}<div class="chips">${['All',...new Set(list.map(p=>p.category))].map(c=>`<button class="chip ${filter.category===c?'selected':''}" onclick="setFilter('category','${c}')">${c==='All'?'All '+(shop?'products':'projects'):c}</button>`).join('')}</div><div class="toolbar"><input id="search" aria-label="Search ${shop?'products':'projects'}" placeholder="${shop?'Search boards, sensors, kits…':'Search projects, ESP32, Arduino, robotics…'}" value="${esc(filter.q)}" oninput="filter.q=this.value;refreshResults('${kind}')">${!shop?`<select aria-label="Branch" onchange="setFilter('branch',this.value)">${options(['All','CSE','ECE','EEE','Mechanical'],filter.branch).replace('>All<','>All branches<')}</select><select aria-label="Technology" onchange="setFilter('tech',this.value)">${options(['All',...list.map(p=>p.technology)],filter.tech).replace('>All<','>All technologies<')}</select><select aria-label="Difficulty" onchange="setFilter('difficulty',this.value)">${options(['All','Beginner','Intermediate','Advanced'],filter.difficulty).replace('>All<','>All levels<')}</select><select aria-label="Maximum budget" onchange="setFilter('budget',this.value)"><option value="All">Any budget</option>${[5000,10000,20000,30000].map(n=>`<option value="${n}" ${filter.budget==n?'selected':''}>Under ${money(n)}</option>`).join('')}</select>`:''}<button class="btn small outline" onclick="resetFilters();render()">Reset filters</button></div><div id="results-count" class="results-count"></div><div id="catalogue-results" class="grid ${shop?'four':''}"></div></div>`}
function resetFilters(){filter={q:'',category:'All',branch:'All',tech:'All',difficulty:'All',budget:'All'}}function setFilter(k,v){filter[k]=v;render()}function refreshResults(kind){const items=filtered(kind);$('#results-count').textContent=items.length+' '+(kind==='shop'?'products':'projects')+' found';$('#catalogue-results').innerHTML=items.length?items.map(kind==='shop'?productCard:projectCard).join(''):'<div class="empty"><h2>No matches yet.</h2><p>Try another component, technology or category.</p><button class="btn outline" onclick="resetFilters();render()">Clear filters</button></div>'}
function specs(obj){return `<div class="specs">${Object.entries(obj).map(([k,v])=>`<div><span>${esc(k)}</span>${esc(v)}</div>`).join('')}</div>`}
function detailPage(id,isProduct){const p=(isProduct?data.products:data.projects).find(x=>x.id===id);if(!p)return notFound();const tabs=isProduct?['Overview','Specifications','Downloads','Reviews']:['Overview','How it works','Components','Gallery','Video','Documents'];return `<div class="container"><div class="page-head"><div class="breadcrumb"><a href="#/">Home</a> / <a href="#/${isProduct?'shop':'projects'}">${isProduct?'Shop':'Projects'}</a> / ${esc(p.title)}</div></div><section class="detail"><div><div class="detail-img ${isProduct?'product-img':''}">${image(p.image,p.title,'',true)}</div><p class="note" style="margin-top:12px">Illustrative image · Sample catalogue item. Final product photographs and specifications will be confirmed before launch.</p></div><div><span class="eyebrow">${esc(p.category)}</span><h1>${esc(p.title)}</h1><p>${esc(p.description)}</p>${isProduct?`<div class="price">${money(p.price)} <small>Demo price</small></div><div class="stock">${p.stock} units available · SKU ${esc(p.sku)}</div>${specs(p.specs)}<div class="button-row"><div class="quantity"><button aria-label="Decrease quantity" onclick="qty=Math.max(1,qty-1);$('#detail-qty').textContent=qty">−</button><span id="detail-qty">${qty}</span><button aria-label="Increase quantity" onclick="qty=Math.min(${p.stock},qty+1);$('#detail-qty').textContent=qty">+</button></div><button class="btn blue" onclick="addCart('${p.id}',qty)">Add to bag</button><button class="btn outline" onclick="if(addCart('${p.id}',qty))location.hash='/checkout'">Buy now</button></div><button class="text-link" style="background:none;border:0;padding:0" onclick="openEnquiry('Product','${p.id}')">Ask a technical question</button>`:`${specs({Technology:p.technology,Branch:p.branch,Difficulty:p.difficulty,Budget:'From '+money(p.budget)})}<div class="button-row"><button class="btn blue" onclick="openEnquiry('Project','${p.id}')">Request this project</button><button class="btn outline" onclick="openEnquiry('WhatsApp','${p.id}')">WhatsApp enquiry</button></div><p class="note">Custom hardware, software and documentation available. Indicative budget; final scope is quoted after review.</p>`}</div></section><div class="tabs" role="tablist">${tabs.map(t=>`<button role="tab" aria-selected="${tab===t}" class="${tab===t?'active':''}" onclick="tab='${t}';render()">${t}</button>`).join('')}</div><div class="tab-content">${detailTab(p,isProduct)}</div><section class="section"><div class="section-header"><h2>${isProduct?'Complete your workbench.':'Explore another possibility.'}</h2></div><div class="grid">${(isProduct?data.products:data.projects).filter(x=>x.id!==p.id).slice(0,3).map(isProduct?productCard:projectCard).join('')}</div></section></div>`}
function detailTab(p,product){if(tab==='Specifications')return `<h2>Technical specifications</h2>${specs(p.specs)}`;if(tab==='How it works')return `<h2>From input to action.</h2><p>${esc(p.how)}</p><div class="flow"><span>Sensor / input</span><span>Controller / processing</span><span>Action / output</span><span>Dashboard / review</span></div><p class="note">Illustrative system flow. Final block diagram will reflect the agreed build.</p>`;if(tab==='Components')return `<h2>Inside the build.</h2><p>Explore compatible sample components.</p><div class="grid">${p.components.map(id=>data.products.find(x=>x.id===id)).filter(Boolean).map(productCard).join('')}</div>`;if(tab==='Gallery')return `<h2>Engineering inspiration</h2><div class="gallery">${image(p.image,p.title)}${image(IMG.lab,'Engineering laboratory')}</div><p class="note">Illustrative photos; actual build gallery will be added by the CLASSS team.</p>`;if(tab==='Video')return `<div class="video-placeholder"><h2>Project demonstration</h2><p style="color:#bed0dc">The final project video will be embedded here from the team's approved channel.</p><button class="btn outline" onclick="downloadDoc('${p.id}')">View sample demo script</button></div>`;if(tab==='Documents'||tab==='Downloads')return `<h2>Project resources</h2><p>Download a sample technical outline for the team review.</p><button class="btn outline" onclick="downloadDoc('${p.id}')">Download sample outline (.txt)</button><p class="note">Demonstration document; manufacturer datasheets and approved PDFs will be supplied for the production catalogue.</p>`;if(tab==='Reviews')return `<h2>Sample customer feedback</h2><div class="review"><b>★★★★★ · Useful for our robotics workshop</b><p>Clear setup guidance and a practical starting point for students.</p><small>Demo reviewer · Illustrative feedback</small></div>`;return `<h2>${product?'Built for your next experiment.':'An idea you can make your own.'}</h2><p>${esc(p.description)}</p>${!product?`<h3>Applications</h3><p>${esc(p.applications)}</p><h3>Customization</h3><p>Discuss controller choices, dimensions, dashboard features, enclosure design and documentation with the team.</p>`:'<p>Confirm compatibility, power requirements and exact variant before ordering. Contact the team for project bundles or larger quantities.</p>'}`}
function downloadDoc(id){const p=[...data.products,...data.projects].find(x=>x.id===id);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([`CLASSS PROJECTS — DEMO TECHNICAL OUTLINE\n\n${p.title}\n\n${p.description}\n\n${p.how||JSON.stringify(p.specs,null,2)}\n\nThis document contains illustrative content for a team mockup. It is not a manufacturer datasheet or final deliverable.`],{type:'text/plain'}));a.download=id+'-sample.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function addCart(id,n=1){const p=data.products.find(x=>x.id===id);if(!p||!Number.isInteger(n)||n<1)return false;const row=data.cart.find(x=>x.id===id),total=(row?.qty||0)+n;if(total>p.stock){toast('Only '+p.stock+' available in this demo.');return false}if(row)row.qty=total;else data.cart.push({id,qty:n});save();toast('Added to your bag');return true}function changeCart(id,n){const r=data.cart.find(x=>x.id===id),p=data.products.find(x=>x.id===id);if(!r||!p)return;r.qty=Math.min(p.stock,r.qty+n);if(r.qty<=0)data.cart=data.cart.filter(x=>x.id!==id);save();render()}function subtotal(){return data.cart.reduce((n,r)=>n+(data.products.find(p=>p.id===r.id)?.price||0)*r.qty,0)}function shipping(){return subtotal()>=2000?0:60}function cartRows(){return data.cart.map(r=>{const p=data.products.find(x=>x.id===r.id);return `<div class="cart-row">${image(p.image,p.title)}<div><h3><a href="#/product/${p.id}">${esc(p.title)}</a></h3><span class="note">${esc(p.sku)} · ${money(p.price)}</span><br><button class="remove" onclick="data.cart=data.cart.filter(x=>x.id!=='${p.id}');save();render()">Remove</button></div><div class="quantity"><button aria-label="Decrease ${esc(p.title)} quantity" onclick="changeCart('${p.id}',-1)">−</button><span>${r.qty}</span><button aria-label="Increase ${esc(p.title)} quantity" onclick="changeCart('${p.id}',1)">+</button></div><strong>${money(p.price*r.qty)}</strong></div>`}).join('')}function summary(){return `<div class="summary-row"><span>Subtotal</span><b>${money(subtotal())}</b></div><div class="summary-row"><span>Demo shipping</span><b>${shipping()?money(shipping()):'Free'}</b></div><div class="summary-row total"><span>Total</span><span>${money(subtotal()+shipping())}</span></div><p class="note">Demo totals only. Production taxes, shipping rules and payment charges will be configured in WooCommerce.</p>`}
function cartPage(){return `<div class="container">${pageHead('Shopping bag','Your next build, ready to go.','Review your components before continuing.')} ${data.cart.length?`<div class="form-layout"><div>${cartRows()}<div class="button-row"><a class="btn outline" href="#/shop">Continue shopping</a></div></div><aside class="panel"><h2>Order summary</h2>${summary()}<a class="btn blue" style="width:100%" href="#/checkout">Continue to checkout</a></aside></div>`:`<div class="empty" style="margin-bottom:65px"><h2>Your bag is waiting for an idea.</h2><p>Explore boards, sensors and robotics kits.</p><a class="btn blue" href="#/shop">Explore the shop</a></div>`}</div>`}
function checkout(){if(!data.cart.length)return cartPage();if(!session)return `<div class="container">${pageHead('Checkout','Sign in to continue.','Use a sample customer account to explore checkout and order tracking.')}<div class="button-row"><a class="btn blue" href="#/login">Sign in with a demo account</a><a class="btn outline" href="#/cart">Back to bag</a></div><div class="notice">No real payment is collected in this preview.</div></div>`;return `<div class="container">${pageHead('Checkout','Let’s get your build started.','Sample checkout. Please use dummy contact and address details.')}<div class="form-layout"><form class="panel" onsubmit="placeOrder(event)"><h2>Delivery details</h2><div class="form-grid"><label>Name<input name="name" required value="${esc(session.name)}"></label><label>Email<input type="email" name="email" required value="${esc(session.email)}" readonly></label><label>Mobile<input name="mobile" pattern="[0-9]{10}" placeholder="9999999999" value="9999999999" required></label><label>City<input name="city" value="Bengaluru" required></label><label class="full">Address<textarea name="address" required>Demo address — use sample information only</textarea></label><label>State<input name="state" value="Karnataka" required></label><label>PIN code<input name="pin" pattern="[0-9]{6}" value="560001" required></label><label>Demo payment outcome<select name="outcome"><option value="paid">Successful payment</option><option value="failed">Failed payment</option></select></label></div><div class="notice">Payment simulation only. No card, UPI or banking details are requested.</div><button class="btn blue" type="submit">Place demo order</button></form><aside class="panel"><h2>Your order</h2>${data.cart.map(r=>{const p=data.products.find(x=>x.id===r.id);return `<div class="summary-row"><span>${esc(p.title)} × ${r.qty}</span><b>${money(p.price*r.qty)}</b></div>`}).join('')}${summary()}</aside></div></div>`}
function placeOrder(e){e.preventDefault();const f=new FormData(e.target);if(f.get('outcome')==='failed'){toast('Demo payment failed. Your bag is saved; try again.');return}if(data.cart.some(r=>r.qty>data.products.find(x=>x.id===r.id).stock)){toast('Stock changed. Please review your bag.');return}const o={id:'CLS-'+Date.now().toString().slice(-8),email:session.email,customer:f.get('name'),date:dateNow(),total:subtotal()+shipping(),status:'Processing',payment:'Demo paid',items:clone(data.cart),address:[f.get('address'),f.get('city'),f.get('state'),f.get('pin')].join(', ')};data.cart.forEach(r=>data.products.find(x=>x.id===r.id).stock-=r.qty);data.orders.unshift(o);data.notifications.unshift({email:session.email,message:'Order '+o.id+' confirmed (simulated email)',date:dateNow()});data.cart=[];save();location.hash='/order/'+o.id}
function orderSuccess(id){const o=data.orders.find(x=>x.id===id&&x.email===session?.email);if(!o)return notFound();return `<div class="container"><div class="success"><div class="success-mark">✓</div><span class="eyebrow">Demo order confirmed</span><h1>Your next build is on its way.</h1><p>Order <b>${esc(o.id)}</b> · ${money(o.total)}<br>A confirmation has been added to your demo notifications. No real payment, email or shipment was created.</p><div class="panel" style="text-align:left">${o.items.map(r=>`<div class="summary-row"><span>${esc(data.products.find(x=>x.id===r.id)?.title)} × ${r.qty}</span></div>`).join('')}<p>${esc(o.address)}</p></div><div class="button-row" style="justify-content:center"><a class="btn blue" href="#/account/orders">Track demo order</a><a class="btn outline" href="#/shop">Continue exploring</a></div></div></div>`}
function fields(context){return `<div class="form-grid"><label>Name<input name="name" required value="${esc(session?.name||'')}"></label><label>Email<input name="email" type="email" required value="${esc(session?.email||'')}"></label><label>Mobile<input name="mobile" pattern="[0-9]{10}" required placeholder="10-digit demo number"></label><label>School / college / company<input name="org" placeholder="Your institution"></label><label class="full">Requirement<textarea name="requirement" required>${esc(context||'')}</textarea></label><label>Required by<input name="deadline" type="date" min="${new Date().toISOString().slice(0,10)}"></label></div>`}
function openEnquiry(type,id){if(type==='WhatsApp'){openWhatsApp(id);return}const p=[...data.projects,...data.products].find(x=>x.id===id),context=p?.title||id;$('#dialog-content').innerHTML=`<span class="eyebrow">${type==='WhatsApp'?'WhatsApp message preview':esc(type)+' enquiry'}</span><h2>${type==='WhatsApp'?'Start the conversation.':'Tell us about your build.'}</h2>${type==='WhatsApp'?`<div class="notice">Hi CLASSS Projects, I am interested in ${esc(context)}.</div><p class="note">A production WhatsApp number has not been configured. This saves a demo enquiry; it does not send a message.</p>`:''}<form onsubmit="submitEnquiry(event,'${type==='WhatsApp'?'Project':type}')">${fields(context)}<div class="notice">Use sample details. This request is saved only in this browser for the demo.</div><button type="submit" class="btn blue">Save demo enquiry</button></form>`;$('#detail-dialog').showModal()}
function submitEnquiry(e,type){e.preventDefault();const f=new FormData(e.target),file=e.target.querySelector('input[type=file]')?.files[0];if(file){const ext=file.name.split('.').pop().toLowerCase(),allowed=type==='3D Printing'?['stl','obj','step','stp']:['xlsx','xls','csv','pdf'];if(!allowed.includes(ext)||file.size>20*1024*1024){toast('Choose a supported file under 20 MB.');return}}const extra=type==='3D Printing'?` · ${f.get('material')} · ${f.get('colour')} · ${f.get('quantity')} unit(s)`:'';const enq={id:'ENQ-'+Date.now().toString().slice(-7),type,name:f.get('name'),email:f.get('email'),org:f.get('org'),requirement:f.get('requirement')+extra,deadline:f.get('deadline'),file:file?.name||'',status:'New',quote:0,date:dateNow()};data.enquiries.unshift(enq);data.notifications.unshift({email:enq.email,message:enq.type+' request '+enq.id+' received (simulated email)',date:dateNow()});save();$('#detail-dialog').close();$('#app').innerHTML=`<div class="container"><div class="success"><div class="success-mark">✓</div><span class="eyebrow">Demo request received</span><h1>We’ve got your requirement.</h1><p>Reference ${enq.id}. Explore the admin demo to review it and send a sample quotation.</p><div class="notice">Only the selected filename was recorded. File contents were not uploaded, and no message was sent.</div><div class="button-row" style="justify-content:center"><a class="btn blue" href="#/account/enquiries">My enquiries</a><a class="btn outline" href="#/">Return home</a></div></div></div>`;window.scrollTo(0,0)}
function printing(){return `<div class="container">${pageHead('3D printing','Your design. Made physical.','Prototype an enclosure, print a mechanism or bring a classroom model to life. Share your design for a quotation.')}<div class="form-layout"><form class="panel" onsubmit="submitEnquiry(event,'3D Printing')"><h2>Request a print</h2>${fields('I need a custom 3D-printed part.')}<div class="form-grid" style="margin-top:20px"><label>Material<select name="material" onchange="printEstimate()" id="print-material">${options(data.materials,'PLA')}</select></label><label>Colour<select name="colour"><option>White</option><option>Black</option><option>Blue</option><option>Custom</option></select></label><label>Quantity<input name="quantity" id="print-quantity" type="number" min="1" max="1000" value="1" required oninput="printEstimate()"></label><label>Estimated weight per part (g)<input id="print-weight" type="number" min="1" max="10000" value="50" oninput="printEstimate()"></label><div class="upload"><label for="model-file">Attach a model</label><input id="model-file" name="file" type="file" accept=".stl,.obj,.step,.stp" required><p>STL, OBJ or STEP · Up to 20 MB · Demo records filename only</p></div></div><div class="notice" id="print-estimate"></div><button class="btn blue" type="submit">Request demo quotation</button></form><aside><div class="card"><div class="card-media" style="height:260px">${image(IMG.printer,'3D printing in a school workshop')}</div><div class="card-body"><h3>From prototype to final part.</h3><p>Material choice, infill, finish and print orientation affect the final result.</p></div></div><div class="panel" style="margin-top:24px"><h2>What happens next</h2><div class="steps"><div class="step"><div><b>Share your model</b><p>Tell us material, colour, quantity and deadline.</p></div></div><div class="step"><div><b>Engineering review</b><p>Check geometry, suitability and production needs.</p></div></div><div class="step"><div><b>Quote & print</b><p>Approve the scope before production starts.</p></div></div></div><a href="#/shop" class="text-link" style="display:block;margin-top:22px">Explore printers & components</a></div></aside></div></div>`}
function printEstimate(){const m=$('#print-material')?.value,q=Number($('#print-quantity')?.value),w=Number($('#print-weight')?.value);if(!$('#print-estimate'))return;const rate={PLA:4,PETG:5,ABS:5,Resin:8}[m]||4;$('#print-estimate').textContent=q>0&&w>0?`Illustrative estimate: ${money(Math.round(150+w*rate*q))}. Uses your entered weight; no file geometry or slicing is analysed. Final quote requires review.`:'Enter a positive quantity and weight to see a sample estimate.'}
function bulk(){return `<div class="container">${pageHead('Institutions & bulk orders','One requirement. A complete solution.','For schools, colleges, labs, companies and dealers. Share a bill of materials or tell us what you’re building.')}<div class="form-layout"><form class="panel" onsubmit="submitEnquiry(event,'Bulk')"><h2>Share your requirement</h2>${fields('')}<div class="form-grid" style="margin-top:20px"><label>Customer type<select name="customer_type"><option>College / university</option><option>School / STEM lab</option><option>Company / startup</option><option>Dealer</option></select></label><label>Expected quantity<input name="quantity" type="number" min="1" value="20" required></label><div class="upload"><label for="bom-file">Attach your BOM or requirement sheet</label><input id="bom-file" type="file" name="file" accept=".xlsx,.xls,.csv,.pdf"><p>Excel, CSV or PDF · Up to 20 MB · Optional · Filename only in this demo</p></div></div><div class="notice">Demo requests stay in this browser. No file contents or external messages are transmitted.</div><button class="btn blue">Request a bulk quote</button></form><aside class="panel"><span class="eyebrow">Built around your institution</span><h2>A practical path to delivery.</h2><div class="steps">${[['Share','Upload a BOM or describe the lab.'],['Review','We check sourcing and availability.'],['Quote','Compare price, lead time and terms.'],['Confirm','Approve your quotation and PO.'],['Fulfil','Delivery, setup and support.']].map(x=>`<div class="step"><div><b>${x[0]}</b><p>${x[1]}</p></div></div>`).join('')}</div></aside></div></div>`}
const services=[['project','Project development','Hardware, software and documentation around your academic or industrial requirement.',['School & final-year projects','Custom embedded systems','PCB design & prototyping']],['automate','Industrial & lab solutions','Engineering support for practical automation and learning environments.',['PLC & industrial automation','STEM / ATL lab setup','Prototyping & installation']],['code','Website development','Build a digital presence that supports your business.',['Company & service websites','Ecommerce & portfolios','SEO, maintenance & support']],['app','App development','Connected applications for customers, teams and smart devices.',['Android / iOS applications','Business & admin dashboards','APIs & cloud integrations']],['network','IoT solutions','Bring connected hardware, firmware and cloud software together.',['Sensor monitoring & control','Agriculture & industrial IoT','Custom devices & enclosures']],['print','Design & 3D printing','Move from concept to CAD, enclosure and physical prototype.',['Mechanical CAD & models','Functional printed parts','Materials & finishing']]];
function servicesPage(){return `<div class="container">${pageHead('Services','Engineering, end to end.','One team for your idea, electronics, software, cloud dashboard and physical prototype.')}<div class="grid section">${services.map((s,i)=>`<article class="card service-card"><div class="service-icon">${icon(s[0])}</div><h3>${s[1]}</h3><p>${s[2]}</p><ul>${s[3].map(x=>`<li>${x}</li>`).join('')}</ul><button class="btn small outline" onclick="openEnquiry('Service','${s[1]}')">Discuss your requirement</button></article>`).join('')}</div><div class="service-banner"><span class="eyebrow">Digital & IoT solutions</span><h2>Connect every part of your idea.</h2><div class="flow">${['Website / app','Electronics & firmware','Cloud & dashboard','3D-printed enclosure','Installation & support'].map(x=>`<span>${x}</span>`).join('')}</div></div></div>`}
function future(){return `<div class="container">${pageHead('Future Tech','Explore what’s possible next.','Robotics, drones, edge AI and immersive technology. Start with a discussion about your application.')}<div class="grid section">${[['Robotics & AI hardware',IMG.robot,'Robotic arms, machine vision and intelligent prototypes.'],['Drones & smart devices',IMG.drone,'Aerial robotics, connected systems and sensing.'],['Edge AI & connected hardware',IMG.esp32,'Local processing, low-latency monitoring and sensor dashboards.']].map(x=>`<article class="card"><div class="card-media">${image(x[1],x[0])}</div><div class="card-body"><div class="meta">Application-led engineering</div><h3>${x[0]}</h3><p>${x[2]}</p><button class="btn small outline" onclick="openEnquiry('Future Tech','${x[0]}')">Explore a solution</button></div></article>`).join('')}</div><div class="service-banner"><h2>VR / AR-MR & wearables</h2><p>Discuss training experiences, interactive visualisation and wearable prototypes. These are enquiry-led services in the demo.</p><button class="btn blue" onclick="openEnquiry('Future Tech','VR / AR-MR & wearables')">Discuss an application</button></div><div class="panel" style="margin-bottom:50px"><span class="eyebrow">Project discovery preview</span><h2>Describe your idea.</h2><p>Try “ESP32” or “robotics”. This demo uses keyword matching; AI-assisted search is a future integration.</p><form class="toolbar" onsubmit="event.preventDefault();resetFilters();filter.q=this.idea.value;route='/projects';location.hash='/projects';render()"><input name="idea" aria-label="Describe your project idea" placeholder="I want to explore robotics"><button class="btn blue">Find projects</button></form></div></div>`}
function login(){return `<div class="container"><div class="login"><div class="login-info"><span class="eyebrow" style="color:var(--mint)">Explore your CLASSS</span><h1>A place for every part of your build.</h1><p>Try the customer journey or review the team's catalogue and enquiry workspace.</p><div class="demo-account"><b>Customer account</b>student@example.com<br>Password: ClasssDemo123!<br><button class="btn small outline" onclick="fillLogin('customer')">Use customer details</button></div><div class="demo-account"><b>Admin account</b>admin@example.com<br>Password: ClasssAdmin123!<br><button class="btn small outline" onclick="fillLogin('admin')">Use admin details</button></div></div><div class="login-form"><h2>Welcome back.</h2><p class="note">Demo accounts only. Use the credentials provided.</p><form onsubmit="signIn(event)"><label>Email<input id="login-email" name="email" type="email" autocomplete="username" required></label><label>Password<input id="login-password" name="password" type="password" autocomplete="current-password" required></label><button class="btn blue" style="width:100%">Sign in</button><p id="login-error" role="alert" style="color:#a53939;font-size:13px"></p></form><div class="notice">These are simulated roles, not secure production authentication. Data and edits remain in this browser. Do not enter real credentials.</div><a class="text-link" href="#/">Continue exploring the website</a></div></div></div>`}
function fillLogin(role){$('#login-email').value=role==='admin'?'admin@example.com':'student@example.com';$('#login-password').value=role==='admin'?'ClasssAdmin123!':'ClasssDemo123!'}
function signIn(e){e.preventDefault();const f=new FormData(e.target),email=String(f.get('email')).toLowerCase().trim(),pass=f.get('password');if(email==='admin@example.com'&&pass==='ClasssAdmin123!')session={role:'admin',name:'CLASSS Team',email};else if(email==='student@example.com'&&pass==='ClasssDemo123!')session={role:'customer',name:'Vikram Rao',email};else{$('#login-error').textContent='Use one of the provided demo accounts.';return}sessionStorage.setItem('classs-demo-user',JSON.stringify(session));location.hash=session.role==='admin'?'/admin':'/account';toast('Signed in to the '+session.role+' demo')}
function logout(){session=null;sessionStorage.removeItem('classs-demo-user');location.hash='/login';toast('Signed out')}
function statusTag(s){return `<span class="status ${['Completed','Delivered','Confirmed','Accepted'].includes(s)?'green':['New','Processing','Quote sent'].includes(s)?'amber':''}">${esc(s)}</span>`}
function ordersTable(list,admin=false){return `<div class="table-wrap"><table><thead><tr><th>Order</th><th>${admin?'Customer':'Date'}</th><th>Total</th><th>Status</th><th>Details</th></tr></thead><tbody>${list.map(o=>`<tr><td><b>${esc(o.id)}</b><br><span class="note">${o.items.reduce((n,r)=>n+r.qty,0)} items · ${esc(o.payment)}</span></td><td>${esc(admin?o.customer:o.date)}</td><td>${money(o.total)}</td><td>${admin?`<select aria-label="Status for ${o.id}" onchange="updateOrder('${o.id}',this.value)">${options(['Processing','Shipped','Delivered','Cancelled'],o.status)}</select>`:statusTag(o.status)}</td><td><button class="btn small outline" onclick="viewOrder('${o.id}')">View</button></td></tr>`).join('')||'<tr><td colspan="5">No demo orders yet.</td></tr>'}</tbody></table></div>`}
function viewOrder(id){const o=data.orders.find(x=>x.id===id&&(session?.role==='admin'||x.email===session?.email));if(!o)return;$('#dialog-content').innerHTML=`<span class="eyebrow">Demo order</span><h2>${esc(o.id)}</h2>${statusTag(o.status)}<p style="margin-top:20px">${esc(o.customer)} · ${esc(o.date)}</p>${o.items.map(r=>`<p>${esc(data.products.find(x=>x.id===r.id)?.title)} × ${r.qty}</p>`).join('')}<p><b>Total ${money(o.total)}</b></p><p>${esc(o.address)}</p><div class="notice">Tracking and email updates are simulated in this preview.</div>`;$('#detail-dialog').showModal()}
function enquiryTable(list,admin=false){return `<div class="table-wrap"><table><thead><tr><th>Request</th><th>${admin?'Customer':'Requirement'}</th><th>Status</th><th>Quote</th><th>Action</th></tr></thead><tbody>${list.map(e=>`<tr><td><b>${esc(e.id)}</b><br><span class="note">${esc(e.type)} · ${esc(e.date)}</span></td><td>${esc(admin?e.org||e.name:e.requirement.slice(0,42))}</td><td>${admin?`<select aria-label="Status for ${e.id}" onchange="updateEnquiry('${e.id}',this.value)">${options(['New','Contacted','Quote sent','Confirmed','Completed'],e.status)}</select>`:statusTag(e.status)}</td><td>${e.quote?money(e.quote):'Awaiting review'}</td><td><button class="btn small outline" onclick="viewEnquiry('${e.id}')">${admin?'Review':'View quote'}</button></td></tr>`).join('')||'<tr><td colspan="5">No requests yet. Explore a project or request a quote.</td></tr>'}</tbody></table></div>`}
function viewEnquiry(id){const e=data.enquiries.find(x=>x.id===id&&(session?.role==='admin'||x.email===session?.email));if(!e)return;$('#dialog-content').innerHTML=`<span class="eyebrow">${esc(e.type)} request</span><h2>${esc(e.id)}</h2>${statusTag(e.status)}<p style="margin-top:20px">${esc(e.name)} · ${esc(e.org)}</p><p>${esc(e.requirement)}</p><p class="note">${esc(e.email)} · ${e.deadline?'Deadline '+esc(e.deadline):'No deadline specified'}${e.file?'<br>Attached filename: '+esc(e.file)+' (file content not uploaded)':''}</p>${session.role==='admin'?`<form onsubmit="sendQuote(event,'${e.id}')"><label>Sample quotation amount (₹)<input name="amount" type="number" min="1" step="1" required value="${e.quote||6500}"></label><label style="margin-top:15px">Team notes<textarea name="notes">${esc(e.notes||'')}</textarea></label><button class="btn blue" style="margin-top:20px">Save & send demo quote</button></form>`:e.quote?`<div class="notice">Sample quote: <b>${money(e.quote)}</b><br>${esc(e.notes||'Final scope, delivery and taxes to be confirmed.')}</div>${e.status==='Quote sent'?`<button class="btn blue" onclick="acceptQuote('${e.id}')">Accept demo quotation</button>`:''}`:'<div class="notice">The team is reviewing your requirement.</div>'}`;$('#detail-dialog').showModal()}
function updateOrder(id,status){if(session?.role!=='admin')return;const o=data.orders.find(x=>x.id===id);if(status==='Cancelled'&&o.status!=='Cancelled')o.items.forEach(r=>data.products.find(x=>x.id===r.id).stock+=r.qty);if(o.status==='Cancelled'&&status!=='Cancelled'){toast('Cancelled demo orders cannot be reopened.');render();return}o.status=status;data.notifications.unshift({email:o.email,message:'Order '+id+' updated to '+status+' (simulated)',date:dateNow()});save();toast('Order status updated')}
function updateEnquiry(id,status){if(session?.role!=='admin')return;data.enquiries.find(x=>x.id===id).status=status;save();toast('Enquiry status updated')}
function sendQuote(ev,id){ev.preventDefault();if(session?.role!=='admin')return;const f=new FormData(ev.target),e=data.enquiries.find(x=>x.id===id);e.quote=Number(f.get('amount'));e.notes=f.get('notes');e.status='Quote sent';data.notifications.unshift({email:e.email,message:'Quote '+id+' is ready: '+money(e.quote)+' (simulated email)',date:dateNow()});save();$('#detail-dialog').close();render();toast('Demo quotation saved')}
function acceptQuote(id){const e=data.enquiries.find(x=>x.id===id&&x.email===session?.email);if(!e)return;e.status='Confirmed';data.notifications.unshift({email:e.email,message:'Quote '+id+' accepted (simulated)',date:dateNow()});save();$('#detail-dialog').close();render();toast('Demo quotation accepted')}
function dashboardShell(admin,section,body){const links=admin?[['overview','Overview'],['products','Products'],['projects','Projects CMS'],['enquiries','Enquiries'],['bulk','Bulk quotes'],['printing','3D printing'],['orders','Orders'],['trending','Featured & trending']]:[['overview','Overview'],['orders','My orders'],['enquiries','My enquiries'],['notifications','Notifications'],['profile','My profile']];return `<div class="container dashboard"><aside><h3>${admin?'CLASSS Workspace':esc(session.name)}</h3><small>${admin?'Admin demo':'Customer demo'}</small>${links.map(x=>`<a href="#/${admin?'admin':'account'}/${x[0]}" class="${section===x[0]?'active':''}">${x[1]}</a>`).join('')}<a href="#/shop">Visit storefront</a><button class="btn small outline" style="margin:10px" onclick="logout()">Sign out</button></aside><div class="content">${body}</div></div>`}
function account(){if(!session)return login();if(session.role==='admin')return admin();const os=data.orders.filter(o=>o.email===session.email),es=data.enquiries.filter(e=>e.email===session.email),ns=data.notifications.filter(n=>n.email===session.email),section=route.split('/')[2]||'overview';let body=`<div class="dashboard-head"><div><span class="eyebrow">Your CLASSS</span><h1>Hello, ${esc(session.name.split(' ')[0])}.</h1><p>Everything for your next build, in one place.</p></div><a class="btn small outline" href="#/projects">Explore projects</a></div>`;if(section==='orders')body+='<div class="panel"><h2>Your orders</h2>'+ordersTable(os)+'</div>';else if(section==='enquiries')body+='<div class="panel"><h2>Requests & quotations</h2>'+enquiryTable(es)+'</div>';else if(section==='notifications')body+=`<div class="panel"><h2>Demo notifications</h2>${ns.map(n=>`<div class="review"><p>${esc(n.message)}</p><small>${esc(n.date)}</small></div>`).join('')||'<p>No new demo notifications. Try placing an order or requesting a quote.</p>'}<div class="notice">No real emails, SMS or WhatsApp messages have been sent.</div></div>`;else if(section==='profile')body+=`<form class="panel" onsubmit="event.preventDefault();session.name=this.name.value;sessionStorage.setItem('classs-demo-user',JSON.stringify(session));render();toast('Demo profile updated')"><h2>Your profile</h2><label>Name<input name="name" required value="${esc(session.name)}"></label><label style="margin-top:20px">Email<input value="${esc(session.email)}" readonly></label><button class="btn blue" style="margin-top:20px">Save profile</button><div class="app-note" style="margin-top:25px">Use the browser’s Install app or Add to Home Screen option to try the mobile web app.</div></form>`;else body+=`<div class="stats"><div class="stat"><span>Orders</span><strong>${os.length}</strong><small>Your sample purchases</small></div><div class="stat"><span>Open enquiries</span><strong>${es.filter(x=>x.status!=='Completed').length}</strong><small>Projects, prints & quotes</small></div><div class="stat"><span>Quotes ready</span><strong>${es.filter(x=>x.status==='Quote sent').length}</strong><small>Review and approve</small></div><div class="stat"><span>Notifications</span><strong>${ns.length}</strong><small>Simulated updates</small></div></div><div class="panel"><h2>Recent orders</h2>${ordersTable(os.slice(0,3))}</div><div class="panel" style="margin-top:24px"><h2>Your project enquiries</h2>${enquiryTable(es)}</div>`;return dashboardShell(false,section,body)}
function admin(){if(!session||session.role!=='admin')return `<div class="container">${pageHead('Team workspace','Sign in as the team.','Use the admin demo account to manage sample content, orders and enquiries.')}<a href="#/login" class="btn blue" style="margin-bottom:60px">Admin demo sign in</a></div>`;const section=route.split('/')[2]||'overview';let body=`<div class="dashboard-head"><div><span class="eyebrow">CLASSS team workspace</span><h1>${({overview:'Your business at a glance.',products:'Products & inventory',projects:'Projects CMS',enquiries:'Enquiry pipeline',bulk:'Institutional quotations',printing:'3D printing requests',orders:'Orders & fulfilment',trending:'Featured & trending'}[section]||'Workspace')}</h1><p>Demo changes update this browser’s storefront.</p></div><button class="btn small outline" onclick="resetDemo()">Reset sample data</button></div>`;if(section==='products'||section==='projects'){const list=section==='products'?data.products:data.projects;body+=`<div class="button-row"><button class="btn blue" onclick="editContent('${section}','')">Add ${section==='products'?'product':'project'}</button></div><div class="panel table-wrap"><table><thead><tr><th>Item</th><th>Category</th><th>${section==='products'?'Price / stock':'Technology / budget'}</th><th>Featured</th><th>Manage</th></tr></thead><tbody>${list.map(p=>`<tr><td>${image(p.image,p.title,'mini-image')}<b>${esc(p.title)}</b></td><td>${esc(p.category)}</td><td>${money(p.price||p.budget)}<br><span class="note">${esc(section==='products'?p.stock+' units':p.technology)}</span></td><td>${p.featured?'Yes':'No'}</td><td><button class="btn small outline" onclick="editContent('${section}','${p.id}')">Edit</button></td></tr>`).join('')}</tbody></table></div>`}else if(['enquiries','bulk','printing'].includes(section)){const es=data.enquiries.filter(e=>section==='enquiries'||e.type===(section==='bulk'?'Bulk':'3D Printing'));body+='<div class="panel">'+enquiryTable(es,true)+'</div>';if(section==='printing')body+=`<form class="panel" style="margin-top:24px" onsubmit="event.preventDefault();data.materials=this.materials.value.split(',').map(x=>x.trim()).filter(Boolean);save();toast('Print materials updated')"><h2>Service options</h2><label>Available materials (comma separated)<input name="materials" value="${esc(data.materials.join(', '))}" required></label><button class="btn small blue" style="margin-top:16px">Save materials</button></form>`}else if(section==='orders')body+='<div class="panel">'+ordersTable(data.orders,true)+'</div>';else if(section==='trending')body+=`<div class="panel"><h2>Homepage selections</h2><p>Choose the sample projects and products shown on the homepage.</p>${['projects','products'].map(kind=>`<h3>${kind==='projects'?'Projects':'Products'}</h3>${data[kind].map(p=>`<label style="display:flex;gap:12px;align-items:center;margin:12px 0"><input style="width:auto;margin:0" type="checkbox" ${p.featured?'checked':''} onchange="toggleFeatured('${kind}','${p.id}',this.checked)">${esc(p.title)}</label>`).join('')}`).join('')}</div>`;else body+=`<div class="stats"><div class="stat"><span>Demo sales</span><strong>${money(data.orders.filter(x=>x.status!=='Cancelled').reduce((n,x)=>n+x.total,0))}</strong><small>Sample orders only</small></div><div class="stat"><span>Orders</span><strong>${data.orders.length}</strong><small>${data.orders.filter(x=>x.status==='Processing').length} awaiting fulfilment</small></div><div class="stat"><span>Open enquiries</span><strong>${data.enquiries.filter(x=>x.status!=='Completed').length}</strong><small>Review customer requirements</small></div><div class="stat"><span>Catalogue items</span><strong>${data.products.length+data.projects.length}</strong><small>Projects & products</small></div></div><div class="panel"><h2>Recent enquiries</h2>${enquiryTable(data.enquiries.slice(0,5),true)}</div><div class="panel" style="margin-top:24px"><h2>Recent orders</h2>${ordersTable(data.orders.slice(0,4),true)}</div><div class="notice">Preview workspace only. Production will use WordPress permissions, WooCommerce orders and server-side storage. Analytics shown here are derived from sample data.</div>`;return dashboardShell(true,section,body)}
function toggleFeatured(kind,id,v){if(session?.role!=='admin')return;data[kind].find(x=>x.id===id).featured=v;save();toast('Homepage selection saved')}
function editContent(kind,id){if(session?.role!=='admin')return;const p=data[kind].find(x=>x.id===id)||{},prod=kind==='products';$('#dialog-content').innerHTML=`<span class="eyebrow">${prod?'Product':'Project'} CMS</span><h2>${id?'Edit':'Add'} ${prod?'product':'project'}</h2><form onsubmit="saveContent(event,'${kind}','${id}')"><div class="form-grid"><label class="full">Title<input name="title" value="${esc(p.title||'')}" required></label><label>Category<input name="category" value="${esc(p.category||'')}" required></label><label>${prod?'Price':'Indicative budget'} (₹)<input name="amount" type="number" min="1" value="${p.price||p.budget||500}" required></label>${prod?`<label>Stock<input name="stock" type="number" min="0" value="${p.stock??10}" required></label><label>SKU<input name="sku" value="${esc(p.sku||'CLS-DEMO-'+Date.now().toString().slice(-5))}" required></label>`:`<label>Branch<select name="branch">${options(['CSE','ECE','EEE','Mechanical'],p.branch||'ECE')}</select></label><label>Technology<input name="technology" value="${esc(p.technology||'Arduino')}" required></label><label>Difficulty<select name="difficulty">${options(['Beginner','Intermediate','Advanced'],p.difficulty||'Beginner')}</select></label>`}<label class="full">Description<textarea name="description" required>${esc(p.description||'')}</textarea></label><label class="full">Image URL<input name="image" type="url" value="${esc(p.image||IMG.board)}" required></label><label class="full">SEO title<input name="seo" value="${esc(p.seo||p.title||'')}"></label><label class="full">Featured on homepage<select name="featured"><option value="yes" ${p.featured?'selected':''}>Yes</option><option value="no" ${!p.featured?'selected':''}>No</option></select></label></div><button class="btn blue" style="margin-top:24px">Save demo content</button></form>`;$('#detail-dialog').showModal()}
function saveContent(e,kind,id){e.preventDefault();if(session?.role!=='admin')return;const f=new FormData(e.target),url=f.get('image');if(!/^https:\/\//i.test(url)){toast('Use an HTTPS image URL.');return}const prod=kind==='products';if(prod&&data.products.some(p=>p.id!==id&&p.sku===f.get('sku'))){toast('That SKU already exists.');return}const p=data[kind].find(x=>x.id===id)||{id:'demo-'+Date.now(),specs:{Use:'Demo item'},components:['arduino-uno'],how:'Sample workflow to be supplied by the team.',applications:'Educational demonstration.'};Object.assign(p,{title:f.get('title'),category:f.get('category'),description:f.get('description'),image:url,seo:f.get('seo'),featured:f.get('featured')==='yes'});if(prod)Object.assign(p,{price:Number(f.get('amount')),stock:Number(f.get('stock')),sku:f.get('sku')});else Object.assign(p,{budget:Number(f.get('amount')),branch:f.get('branch'),technology:f.get('technology'),difficulty:f.get('difficulty')});if(!id)data[kind].push(p);save();$('#detail-dialog').close();render();toast('Content saved to the demo storefront')}
function resetDemo(){if(!confirm('Reset all demo products, projects, requests and orders in this browser?'))return;localStorage.removeItem('classs-demo-v1');location.reload()}
function policies(){return `<div class="container">${pageHead('Demo information','A clear view of the experience.','This website is an interactive team mockup for CLASSS Projects.')}<div class="panel section" style="margin-bottom:50px"><h2>What works in this preview</h2><p>Explore the catalogue, filter projects, add products to a bag, complete a simulated checkout, submit sample enquiries, manage demo quotes, edit content and update order statuses.</p><h2>Demo data and privacy</h2><p>Accounts are frontend simulations. Sample data is stored in this browser, and is not shared between devices. Use dummy information only. File contents are not uploaded. Payments, shipping, emails and WhatsApp are simulated. This is not a production WordPress or WooCommerce installation.</p><h2>Production implementation</h2><p>The accompanying WordPress foundation provides a custom theme, project content types and editable fields, WooCommerce support and an enquiry workflow. Real hosting, payment, shipping, notifications, private file storage and production authentication still need configuration and verification.</p><h2>Policy placeholders</h2><p>Shipping, refunds, privacy, warranties and service terms must be supplied and approved by CLASSS before accepting real orders.</p><h2>Image credits</h2><p>Images are illustrative, not photographs of products supplied by CLASSS. Resized/cropped for display. Full credits and licence links appear below.</p><div id="credits-list">Loading credits…</div><div class="app-note" style="margin-top:25px">Installable web app: use Install app where supported, or Safari → Share → Add to Home Screen. Native Android/iOS applications are a separate implementation.</div></div></div>`}
function notFound(){return `<div class="container empty" style="margin:50px auto"><h1>That page is not here.</h1><a href="#/" class="btn blue">Return home</a></div>`}
function render(){const next=location.hash.slice(1)||'/';if(next!==route){tab='Overview';qty=1;if(next.split('/')[1]!==route.split('/')[1])resetFilters()}route=next;document.querySelector('header nav').classList.remove('open');document.querySelectorAll('header nav a,.mobile-dock a').forEach(a=>a.classList.toggle('active',a.hash.slice(1)===route.split('/').slice(0,2).join('/')));let html;if(route==='/')html=home();else if(route==='/projects')html=catalogue('projects');else if(route==='/shop')html=catalogue('shop');else if(route.startsWith('/project/'))html=detailPage(route.split('/')[2],false);else if(route.startsWith('/product/'))html=detailPage(route.split('/')[2],true);else if(route==='/printing')html=printing();else if(route==='/bulk')html=bulk();else if(route==='/services')html=servicesPage();else if(route==='/future')html=future();else if(route==='/cart')html=cartPage();else if(route==='/checkout')html=checkout();else if(route==='/login')html=login();else if(route.startsWith('/account'))html=account();else if(route.startsWith('/admin'))html=admin();else if(route.startsWith('/order/'))html=orderSuccess(route.split('/')[2]);else if(route==='/policies')html=policies();else html=notFound();$('#app').innerHTML=html;$('#app').className=route==='/'?'homepage':'';updateCount();if(route==='/projects'||route==='/shop')refreshResults(route.slice(1));if(route==='/printing')printEstimate();if(route==='/policies')fetch('assets/image-credits.json').then(r=>r.json()).then(list=>{if($('#credits-list'))$('#credits-list').innerHTML=list.map(x=>`<p><a class="text-link" href="${esc(x.source)}" target="_blank" rel="noopener">${esc(x.name)}</a> — ${esc(x.credit)} · <a href="${esc(x.licenseUrl)}" target="_blank" rel="noopener">${esc(x.license)}</a></p>`).join('')}).catch(()=>{if($('#credits-list'))$('#credits-list').textContent='Image credits are included in the project files.'});document.title=(route==='/'?'CLASSS Projects | Build something that matters':route.split('/')[1].replace(/^./,c=>c.toUpperCase())+' | CLASSS Projects — Demo')}
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});render();
let deferredInstall;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#install-button').hidden=false});$('#install-button').addEventListener('click',async()=>{if(deferredInstall){await deferredInstall.prompt();deferredInstall=null;$('#install-button').hidden=true}});if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'search_catalogue',description:'Search the visible CLASSS demo catalogue and navigate to its results.',inputSchema:{type:'object',properties:{query:{type:'string'},kind:{type:'string',enum:['projects','shop']}},required:['query','kind'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.query!=='string'||!['projects','shop'].includes(input.kind))throw new Error('Provide query and a valid catalogue kind.');resetFilters();filter.q=input.query;route='/'+input.kind;location.hash=route;render();return{matches:filtered(input.kind).map(p=>({id:p.id,title:p.title}))}}});document.modelContext.registerTool({name:'add_demo_products_to_bag',description:'Add specified sample products to the visible demo bag; does not place an order.',inputSchema:{type:'object',properties:{items:{type:'array',items:{type:'object',properties:{id:{type:'string'},quantity:{type:'integer',minimum:1}},required:['id','quantity'],additionalProperties:false}}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Array.isArray(input?.items)||input.items.some(r=>!data.products.some(p=>p.id===r.id)||!Number.isInteger(r.quantity)||r.quantity<1))throw new Error('Invalid demo product or quantity.');const staged=clone(data.cart);for(const r of input.items){let row=staged.find(x=>x.id===r.id);if(row)row.qty+=r.quantity;else staged.push({id:r.id,qty:r.quantity})}if(staged.some(r=>r.qty>data.products.find(p=>p.id===r.id).stock))throw new Error('Insufficient demo stock.');data.cart=staged;save();render();return{items:clone(data.cart),subtotal:subtotal()}}})}catch(e){console.warn('Optional WebMCP unavailable',e)}}

function whatsappContext(context){
 const p=[...data.projects,...data.products].find(x=>x.id===context||x.id===route.split('/')[2]);
 if(p)return 'Hi CLASSS Projects, I am interested in '+p.title+'. Please share details and availability.';
 if(route==='/printing')return 'Hi CLASSS Projects, I would like a quotation for a custom 3D-printed part.';
 if(route==='/bulk')return 'Hi CLASSS Projects, I would like to discuss an institutional or bulk order.';
 return 'Hi CLASSS Projects, I would like to discuss a project, components or a custom build.';
}
function whatsappLink(number,message){const n=String(number||'').replace(/[+ ()-]/g,'');if(!/^\d{10,15}$/.test(n))return '';return 'https://wa.me/'+n+'?text='+encodeURIComponent(message);}
function updateWhatsAppLink(){const link=whatsappLink(CONTACT_CONFIG.whatsappNumber,$('#wa-message').value);const a=$('#wa-business-link');a.href=link||'#';a.hidden=!link;$('#wa-unconfigured').hidden=!!link;$('#wa-copy').hidden=!!link;}
function openWhatsApp(context=''){$('#wa-message').value=whatsappContext(context);updateWhatsAppLink();$('#wa-panel').hidden=false;$('#wa-trigger').setAttribute('aria-expanded','true');$('#wa-message').focus?.();}
function closeWhatsApp(){$('#wa-panel').hidden=true;$('#wa-trigger').setAttribute('aria-expanded','false');$('#wa-trigger').focus?.();}
async function copyWhatsAppMessage(){try{await navigator.clipboard.writeText($('#wa-message').value);toast('Message copied. Your business WhatsApp number is still awaiting setup.');}catch{$('#wa-message').select?.();toast('Select and copy the prepared message.');}}
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeWhatsApp()});
